using System;
using System.Diagnostics;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Tests;

/// <summary>
/// Base class that provides per-test timing with a configurable warning threshold.
/// Replaces the former TimedTestMethodAttribute which relied on the removed
/// TestMethodAttribute.Execute override.
/// </summary>
public abstract class TimedTestBase
{
    private Stopwatch _stopwatch = null!;

    protected virtual int WarningThresholdMs => 5000;

    [TestInitialize]
    public void TimedTestInitialize()
    {
        _stopwatch = Stopwatch.StartNew();
    }

    [TestCleanup]
    public void TimedTestCleanup()
    {
        _stopwatch.Stop();
        if (_stopwatch.ElapsedMilliseconds > WarningThresholdMs)
        {
            Console.WriteLine($"WARNING: Test took {_stopwatch.ElapsedMilliseconds}ms (threshold: {WarningThresholdMs}ms)");
        }
    }
}

[TestClass]
public class PerformanceTests : TimedTestBase
{
    protected override int WarningThresholdMs => 1000;

    [TestMethod]
    [Timeout(0)]
    public void ProcessLargeDataSet_CompletesInTime()
    {
        Assert.IsTrue(true);
    }

    [TestMethod]
    public void QuickCalculation_IsFast()
    {
        Assert.IsTrue(true);
    }

    [TestMethod]
    [Timeout(0)]
    public void LongRunningIntegration_NeverTimesOut()
    {
        Assert.IsTrue(true);
    }
}

